/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
/* ==========================================================================
   BFUSION Resource Strain Board

   Palette tokens are the suite brand palette. Every one of them is also a
   Format-pane override in capabilities.json, so a report theme can win; these
   are only the defaults, and they must stay in step with DEFAULT_BAND_PALETTE
   in src/bandColor.ts.
   ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: var(--bf-bg, #FFFFFF);
  position: relative;
  color: var(--bf-text, #1F2430);
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-chart-wrap {
  width: 100%;
  height: 100%;
  display: block;
  background: var(--bf-bg, #FFFFFF);
}
/* ── Landing ─────────────────────────────────────────────────────────────── */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: var(--bf-bg, #FFFFFF);
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted, #667079);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text, #242424);
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule, #E5E7EB);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: var(--bf-muted, #667079);
}
/* ==========================================================================
   The board
   ==========================================================================

   `.rga-board` is a flex COLUMN and does not scroll: the split takes the
   height left after the head, the lede and the stats (`flex:1 1 auto` plus
   `min-height:0`), and the board's own vertical scroll lives on
   `.rga-board-col`. The panel gets its height by being stretched, never from a
   max-height of the viewport — that ignores the chrome above it and runs the
   bottom of the panel, and the rail with it, off the end of the visual.
*/
.rga-board {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  /* The license badge sits at bottom:4px/left:8px. Every visual reserves a
       24px clear-zone so report content never sits beneath it. */
  padding: 14px 0 24px 0;
  overflow: hidden;
}
/* ── Head ────────────────────────────────────────────────────────────────── */
.rga-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  flex: 0 0 auto;
  padding: 0 16px 8px 16px;
  /* Anchors the info popover, which is absolutely positioned to its right. */
  position: relative;
}
/* The suite's circular "i": 20px, italic, hover swaps to the accent. Present
   even when the title is empty, so the affordance is always reachable. */
.rga-header__info {
  flex: 0 0 auto;
  order: 3;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-muted, #667079);
  font-family: inherit;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  padding: 0;
  transition: all 0.15s ease;
}
.rga-header__info:hover {
  color: #fff;
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
  outline: none;
}
.rga-header__info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.rga-header__info-pop {
  position: absolute;
  top: calc(100% + 2px);
  right: 12px;
  z-index: 30;
  width: 320px;
  max-width: calc(100% - 24px);
  max-height: 70vh;
  overflow-y: auto;
  background: var(--bf-tile, #FFFFFF);
  border: 1px solid var(--bf-rule, #E3E6EC);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  padding: 12px 14px;
  color: var(--bf-text, #1F2430);
  font-size: 11px;
  line-height: 1.45;
  text-align: left;
}
.rga-info__title {
  display: block;
  font-weight: 650;
  font-size: 12px;
  /* The suite's 2px accent rule under the popover title. */
  border-bottom: 2px solid #E8612A;
  padding-bottom: 4px;
  margin-bottom: 7px;
}
.rga-info__desc {
  display: block;
  color: var(--bf-muted, #6B7280);
  margin-bottom: 4px;
}
.rga-info__heading {
  display: block;
  margin-top: 9px;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--bf-muted, #9AA0A6);
}
.rga-info__list {
  margin: 3px 0 0 0;
  padding-left: 16px;
}
.rga-info__list li {
  margin: 2px 0;
  color: var(--bf-muted, #6B7280);
}
/* ── Legend ──────────────────────────────────────────────────────────────
   Always on screen, not folded into the popover: the dots and the band
   colours are what a first-time reader has to decode before any number means
   anything, and a legend behind a click is a legend read once. */
.rga-legend {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 18px;
  padding: 8px 16px 6px 16px;
  color: var(--bf-muted, #6B7280);
  /* States that a filter is on. Amber, because the board above it is
       deliberately still describing every role. */
  /* Pushed right: a caption on the whole table, not another key item. */
}
.rga-legend__group {
  display: flex;
  align-items: center;
  gap: 12px;
}
.rga-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.rga-legend__text {
  white-space: nowrap;
}
.rga-legend__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 1.5px solid var(--bf-muted, #6B7280);
  flex: 0 0 auto;
  /* The open dot is white-filled, not hollow, exactly as the plot draws
           it — a transparent centre would let the rule show through. */
}
.rga-legend__dot--open {
  background: var(--bf-tile, #FFFFFF);
}
.rga-legend__swatch {
  width: 9px;
  height: 3px;
  border-radius: 2px;
  flex: 0 0 auto;
}
.rga-legend__tick {
  width: 1px;
  height: 9px;
  background: var(--bf-muted, #9AA0A6);
  flex: 0 0 auto;
}
.rga-legend__hidden {
  margin-left: auto;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--bf-surface-alt, #F4F5F7);
  border: 1px solid #F0DCC0;
  color: #8A5A18;
  white-space: nowrap;
  /* When both chips are present the horizon loses its auto margin, so
           they sit together at the right rather than at opposite ends. */
}
.rga-legend__hidden + .rga-legend__horizon {
  margin-left: 10px;
}
.rga-legend__horizon {
  margin-left: auto;
  color: var(--bf-muted, #9AA0A6);
  white-space: nowrap;
}
.rga-head__titles {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.rga-head__title {
  font-weight: 650;
  color: var(--bf-text, #1F2430);
  line-height: 1.25;
}
.rga-head__subtitle {
  color: var(--bf-muted, #6B7280);
  line-height: 1.3;
}
.rga-head__controls {
  /* Pushed right and allowed to wrap under the title on a narrow visual
       rather than squeezing the segmented control into an ellipsis. */
  margin-left: auto;
  flex-wrap: wrap;
  justify-content: flex-end;
  border-bottom: none;
  padding: 0;
  background: transparent;
}
/* Configuration notices.
 *
 * A real callout, not a line of small orange text. These say the visual is
 * missing a field binding without which half its columns cannot exist, and the
 * reader has to notice that before they trust the board — the previous
 * treatment was quieter than the column headers it was explaining away. */
.rga-notes {
  flex: 0 0 auto;
  margin: 0 16px 8px 16px;
  padding: 7px 10px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  background: var(--bf-surface-alt, #F4F5F7);
  border: 1px solid #F0DCC0;
  border-left: 3px solid #D9A832;
  border-radius: 3px;
}
.rga-notes .bfusion-controls__note {
  color: #8A5A18;
  line-height: 1.4;
}
/* ── Lede ────────────────────────────────────────────────────────────────── */
.rga-lede {
  flex: 0 0 auto;
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 2px 16px 0 16px;
}
.rga-lede__number {
  font-weight: 300;
  line-height: 1;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
  /* The em-dash headline, for a board that cannot answer its own question.
       Faint on purpose: it is the absence of a number, not a number. */
}
.rga-lede__number--muted {
  color: var(--bf-muted, #9AA0A6);
}
.rga-lede__text {
  color: var(--bf-text, #1F2430);
  line-height: 1.3;
  max-width: 320px;
  display: flex;
  flex-direction: column;
}
.rga-lede__caption {
  color: var(--bf-muted, #9AA0A6);
  line-height: 1.3;
  margin-top: 2px;
}
/* ── Stats ───────────────────────────────────────────────────────────────── */
.rga-stats {
  flex: 0 0 auto;
  display: flex;
  gap: 28px;
  padding: 14px 16px 10px 16px;
}
.rga-stat {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.rga-stat__label {
  color: var(--bf-muted, #9AA0A6);
  text-transform: none;
  letter-spacing: 0.01em;
  line-height: 1.2;
}
.rga-stat__value {
  font-weight: 600;
  color: var(--bf-text, #1F2430);
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}
/* ── Split ───────────────────────────────────────────────────────────────── */
.rga-split {
  display: flex;
  flex-direction: row;
  flex: 1 1 auto;
  min-height: 0;
}
.rga-board-col {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0 16px;
  position: relative;
  scrollbar-width: thin;
  scrollbar-color: var(--bf-rule, #E5E7EB) transparent;
}
.rga-board-col::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.rga-board-col::-webkit-scrollbar-thumb {
  background: var(--bf-rule, #E5E7EB);
  border-radius: 3px;
}
/* ── Table ───────────────────────────────────────────────────────────────── */
.rga-table {
  width: 100%;
}
.rga-colhead {
  display: flex;
  align-items: flex-end;
  gap: 0;
  color: var(--bf-muted, #9AA0A6);
  padding: 4px 0 6px 0;
  border-bottom: 1px solid var(--bf-rule, #E3E6EC);
  position: sticky;
  top: 0;
  /* Opaque, because the rows scroll UNDER it. */
  background: var(--bf-bg, #FFFFFF);
  z-index: 2;
}
.rga-colhead__cell {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-weight: 500;
}
.rga-section {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 16px 0 4px 0;
}
.rga-section__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex: 0 0 auto;
}
.rga-section__label {
  font-weight: 650;
  text-transform: none;
  letter-spacing: 0.01em;
}
.rga-section__count {
  color: var(--bf-muted, #9AA0A6);
  font-variant-numeric: tabular-nums;
  font-size: 0.9em;
}
.rga-row {
  display: flex;
  align-items: center;
  gap: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--bf-rule, #E5E7EB) 55%, transparent);
  cursor: pointer;
  outline: none;
  transition: background 0.12s ease, opacity 0.12s ease;
}
.rga-row:hover {
  background: var(--bf-surface, #F5F6F8);
}
.rga-row:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
.rga-row--dimmed {
  opacity: 0.38;
}
.rga-row--selected {
  background: rgba(217, 123, 41, 0.06);
}
.rga-cell {
  min-width: 0;
  display: flex;
  align-items: center;
}
.rga-cell--role {
  font-weight: 550;
  color: var(--bf-text, #1F2430);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: block;
  line-height: 1.3;
  padding-right: 8px;
}
.rga-cell--plot {
  overflow: visible;
}
.rga-plot {
  display: block;
  overflow: visible;
}
.rga-cell--util {
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  gap: 3px;
  position: relative;
  padding-right: 12px;
}
.rga-util__value {
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}
.rga-util__track {
  width: 100%;
  height: 3px;
  border-radius: 2px;
  position: relative;
  /* NOT overflow:hidden — the alert tick is a child and stands taller than
       the bar on purpose, so it reads as a threshold across it rather than as
       another segment of it. The fill is clamped to 100% in the renderer, so
       nothing else here needs clipping. */
}
.rga-util__fill {
  height: 100%;
  border-radius: 2px;
}
/* Over 100%: the fill is clamped at the track's width, and this notch at the
   right-hand end carries the overflow instead of drawing into the next column. */
.rga-util__over {
  position: absolute;
  right: 0;
  top: 0;
  width: 3px;
  height: 100%;
  box-shadow: -1px 0 0 var(--bf-bg, #FFFFFF);
}
/* The alert tick — the slider's value, made visible on every row, so a
   percentage is read against a line rather than against a number the reader
   has to remember from the top of the board.

   Positioned inside .rga-util__track, so its inline `left` percentage is a
   percentage of the BAR. Taller than the bar and centred on it, so it reads as
   a threshold crossing the bar rather than as part of the fill. */
.rga-util__tick {
  position: absolute;
  top: -3px;
  height: 9px;
  width: 1px;
  opacity: 0.9;
  pointer-events: none;
}
.rga-cell--runway {
  justify-content: flex-end;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  line-height: 1.2;
}
/* ── Scroll cue ──────────────────────────────────────────────────────────── */
.rga-scrollcue {
  position: sticky;
  bottom: 6px;
  left: 50%;
  transform: translateX(-50%);
  display: block;
  width: 26px;
  height: 26px;
  padding: 0;
  border-radius: 50%;
  border: 1px solid var(--bf-rule, #E3E6EC);
  background: color-mix(in srgb, var(--bf-tile, #fff) 94%, transparent);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
  color: var(--bf-muted, #6B7280);
  font-size: 15px;
  line-height: 1;
  cursor: pointer;
}
.rga-scrollcue:hover {
  color: var(--bf-text, #1F2430);
  border-color: var(--bf-muted, #9AA0A6);
}
.rga-scrollcue:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/* ==========================================================================
   Suite-shared chrome

   The controls strip, the segmented picker, the insights rail, the scope chip
   and the tooltip card are deliberately the SAME class names and the same
   values as bfusion-FTEDecisionBoard, bfusion-CapacityPlanning and
   bfusion-ResourceHeatmap. The visuals sit on one report page and have to read
   as one product — if you change one, change all four.
   ========================================================================== */
.bfusion-controls {
  display: flex;
  align-items: center;
  gap: 8px 18px;
  flex-wrap: wrap;
  padding: 6px 12px;
  box-sizing: border-box;
  background: var(--bf-tile, #FFFFFF);
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  user-select: none;
}
.bfusion-controls__label {
  font-size: 9.5px;
  font-weight: 650;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bf-muted, #667079);
  white-space: nowrap;
}
.bfusion-controls__note {
  font-size: 10px;
  color: #d97706;
}
.bfusion-seg {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px;
  background: var(--bf-surface-alt, #F4F5F7);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 999px;
}
.bfusion-seg--disabled {
  opacity: 0.5;
}
.bfusion-seg__btn {
  appearance: none;
  border: none;
  background: transparent;
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 550;
  color: var(--bf-muted, #667079);
  padding: 3px 11px;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  line-height: 1.5;
  transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}
.bfusion-seg__btn:hover:not(:disabled) {
  color: var(--bf-text, #242424);
  background: color-mix(in srgb, var(--bf-tile, #fff) 75%, transparent);
}
.bfusion-seg__btn--active {
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-text, #242424);
  font-weight: 650;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}
.bfusion-seg__btn:disabled {
  color: #c4c8ce;
  cursor: not-allowed;
  background: transparent;
}
.bfusion-seg__btn:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/* The alert slider. A native range input, so it is keyboard-operable and
   screen-reader-announced for free — both AppSource Certified requirements
   that a div with a mousemove listener has to re-earn. */
.rga-slider {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  user-select: none;
}
.rga-slider__label {
  font-size: 10.5px;
  color: var(--bf-muted, #6B7280);
  white-space: nowrap;
}
.rga-slider__value {
  font-size: 11px;
  font-weight: 650;
  color: var(--bf-text, #1F2430);
  font-variant-numeric: tabular-nums;
  min-width: 34px;
  text-align: right;
}
.rga-slider__input {
  appearance: none;
  -webkit-appearance: none;
  width: 96px;
  height: 14px;
  background: transparent;
  cursor: pointer;
  margin: 0;
}
.rga-slider__input::-webkit-slider-runnable-track {
  height: 2px;
  border-radius: 2px;
  background: var(--bf-rule, #E3E6EC);
}
.rga-slider__input::-moz-range-track {
  height: 2px;
  border-radius: 2px;
  background: var(--bf-rule, #E3E6EC);
}
.rga-slider__input::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 12px;
  height: 12px;
  margin-top: -5px;
  border-radius: 50%;
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-muted, #9AA0A6);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14);
}
.rga-slider__input::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-muted, #9AA0A6);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14);
}
.rga-slider__input:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
/* Vertical INSIGHTS rail — the panel's only open/close control. */
.bfusion-insight-strip {
  background: var(--bf-surface-alt, #F4F5F7);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  color: var(--bf-muted, #667079);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
  flex: 0 0 26px;
  width: 26px;
}
.bfusion-insight-strip__arrow {
  font-size: 10px;
  line-height: 1;
  color: #D97B29;
}
.bfusion-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 0.18em;
  font-size: 9px;
  font-weight: 650;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
}
.bfusion-insight-strip:hover,
.bfusion-insight-strip:focus {
  background: var(--bf-rule, #E5E7EB);
  color: var(--bf-text, #242424);
  outline: none;
}
.bfusion-insight-strip:hover .bfusion-insight-strip__label,
.bfusion-insight-strip:focus .bfusion-insight-strip__label {
  color: var(--bf-muted, #667079);
}
.bfusion-insight-strip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
.bfusion-scope-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  appearance: none;
  border: 1px solid var(--bf-rule, #E3E6EC);
  background: var(--bf-surface, #F5F6F8);
  border-radius: 999px;
  padding: 2px 8px;
  margin-bottom: 8px;
  font-family: inherit;
  font-size: 10px;
  color: var(--bf-muted, #6B7280);
  cursor: pointer;
  max-width: 100%;
}
.bfusion-scope-chip__text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bfusion-scope-chip__x {
  color: var(--bf-muted, #9AA0A6);
  flex: 0 0 auto;
}
.bfusion-scope-chip:hover {
  border-color: var(--bf-muted, #9AA0A6);
  color: var(--bf-text, #1F2430);
}
.bfusion-scope-chip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/* In-visual tooltip card. The host tooltip service is deliberately not used,
   so this is the same card the sibling visuals draw. */
.bfusion-tooltip {
  position: absolute;
  z-index: 999;
  max-width: 260px;
  padding: 8px 12px;
  pointer-events: none;
  background: color-mix(in srgb, var(--bf-tile, #fff) 97%, transparent);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.12);
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 11px;
  line-height: 1.5;
  color: var(--bf-text, #242424);
}
.bfusion-tooltip__head {
  font-weight: 600;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  padding-bottom: 3px;
  margin-bottom: 4px;
}
.bfusion-tooltip__row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.bfusion-tooltip__label {
  color: var(--bf-muted, #667079);
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
}
.bfusion-tooltip__value {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.bfusion-tooltip__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex: 0 0 auto;
}
/* ── Insight panel ───────────────────────────────────────────────────────── */
.rga-panel {
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 10px 12px;
  border-left: 1px solid var(--bf-rule, #E3E6EC);
  background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--bf-surface, #F5F6F8) 100%);
  scrollbar-width: thin;
  scrollbar-color: var(--bf-rule, #E5E7EB) transparent;
}
.rga-panel::-webkit-scrollbar {
  width: 6px;
}
.rga-panel::-webkit-scrollbar-thumb {
  background: var(--bf-rule, #E5E7EB);
  border-radius: 3px;
}
.rga-panel--stacked {
  flex: 0 0 auto;
  width: 100%;
  border-left: none;
  border-top: 1px solid var(--bf-rule, #E3E6EC);
  max-height: 45%;
}
.rga-panel__header {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding-bottom: 5px;
  border-bottom: 2px solid #E8612A;
  margin-bottom: 10px;
}
.rga-panel__title {
  font-weight: 650;
  color: var(--bf-text, #1F2430);
}
.rga-panel__count {
  color: var(--bf-muted, #9AA0A6);
  font-size: 0.85em;
  margin-left: auto;
}
.rga-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 10px;
}
.rga-kpi {
  border-left: 3px solid var(--bf-muted, #9AA0A6);
  background: var(--bf-bg, #FFFFFF);
  border-radius: 3px;
  padding: 5px 8px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}
.rga-kpi__value {
  font-weight: 650;
  color: var(--bf-text, #1F2430);
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}
.rga-kpi__label {
  color: var(--bf-muted, #6B7280);
  font-size: 0.85em;
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rga-healthbar {
  display: flex;
  height: 5px;
  border-radius: 3px;
  overflow: hidden;
  margin-bottom: 12px;
}
.rga-healthbar__seg {
  height: 100%;
}
.rga-panel__section {
  margin-bottom: 12px;
}
.rga-panel__sectiontitle {
  display: block;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--bf-muted, #9AA0A6);
  margin-bottom: 5px;
}
.rga-smart {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.rga-smart__item {
  border-left: 2px solid var(--bf-muted, #9AA0A6);
  padding: 2px 0 2px 8px;
  color: var(--bf-text, #1F2430);
  line-height: 1.4;
}
/* ── Row focus ───────────────────────────────────────────────────────────
   The prescriptive block, above the board-wide cards. A reader who clicked a
   row is asking about that row. */
.rga-focus {
  border-left: 3px solid var(--bf-muted, #9AA0A6);
  background: var(--bf-tile, #FFFFFF);
  border-radius: 3px;
  padding: 8px 10px;
  margin-bottom: 12px;
}
.rga-focus__name {
  display: block;
  font-weight: 650;
  color: var(--bf-text, #1F2430);
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rga-focus__headline {
  display: block;
  font-weight: 650;
  line-height: 1.3;
  margin-top: 1px;
}
.rga-focus__facts {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 1px 8px;
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px solid var(--bf-surface-alt, #F4F5F7);
}
.rga-focus__fact {
  display: contents;
}
.rga-focus__fact-label {
  color: var(--bf-muted, #6B7280);
}
.rga-focus__fact-value {
  color: var(--bf-text, #1F2430);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  text-align: right;
}
.rga-focus__section {
  display: block;
  margin: 10px 0 4px 0;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--bf-muted, #9AA0A6);
}
.rga-focus__spark {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.rga-focus__axis {
  display: flex;
  justify-content: space-between;
  margin-top: 2px;
  font-size: 9px;
  color: var(--bf-muted, #9AA0A6);
}
.rga-listrow {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0;
  min-width: 0;
}
.rga-listrow__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex: 0 0 auto;
}
.rga-listrow__name {
  color: var(--bf-text, #1F2430);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.rga-listrow__value {
  margin-left: auto;
  color: var(--bf-muted, #6B7280);
  font-variant-numeric: tabular-nums;
  flex: 0 0 auto;
}
/* ── Legend as a filter ─────────────────────────────────────────────────
   The key items are buttons. Reset to look exactly like the static key, with
   a hover and an "off" state; the off state is dimmed AND struck through, so it
   does not rely on colour alone. */
.rga-legend__item--toggle {
  appearance: none;
  border: 1px solid transparent;
  background: transparent;
  font: inherit;
  color: inherit;
  padding: 1px 6px;
  margin: 0 -6px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.12s ease, opacity 0.12s ease;
}
.rga-legend__item--toggle:hover {
  background: var(--bf-surface-alt, #F4F5F7);
}
.rga-legend__item--toggle:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.rga-legend__item--off {
  opacity: 0.45;
}
.rga-legend__item--off .rga-legend__text {
  text-decoration: line-through;
}
button.rga-legend__hidden {
  font: inherit;
  cursor: pointer;
}
button.rga-legend__hidden:hover {
  border-color: #D9A45C;
}
button.rga-legend__hidden:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/* ── Period range ──────────────────────────────────────────────────────── */
.rga-rangebar {
  flex: 0 0 auto;
  border-bottom: 0;
  padding: 2px 16px 4px 16px;
  background: transparent;
}
.rga-range {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex: 1 1 auto;
  min-width: 0;
  /* Two inputs share the rail. The inputs ignore the pointer; their thumbs
       take it, so either handle can be grabbed wherever the two sit. */
}
.rga-range__rail {
  position: relative;
  flex: 1 1 auto;
  min-width: 120px;
  max-width: 420px;
  height: 16px;
}
.rga-range__rail::before {
  content: "";
  position: absolute;
  left: 6px;
  right: 6px;
  top: 7px;
  height: 2px;
  border-radius: 2px;
  background: var(--bf-rule, #E3E6EC);
}
.rga-range__fill {
  position: absolute;
  top: 7px;
  height: 2px;
  margin: 0 6px;
  max-width: calc(100% - 12px);
  border-radius: 2px;
  background: #E8612A;
}
.rga-range__input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 16px;
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
  background: transparent;
  pointer-events: none;
  z-index: 2;
}
.rga-range__input::-webkit-slider-runnable-track {
  height: 2px;
  background: transparent;
}
.rga-range__input::-moz-range-track {
  height: 2px;
  background: transparent;
}
.rga-range__input::-webkit-slider-thumb {
  -webkit-appearance: none;
  pointer-events: auto;
  width: 12px;
  height: 12px;
  margin-top: -5px;
  border-radius: 50%;
  background: var(--bf-tile, #FFFFFF);
  border: 2px solid #E8612A;
  cursor: grab;
}
.rga-range__input::-moz-range-thumb {
  pointer-events: auto;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--bf-tile, #FFFFFF);
  border: 2px solid #E8612A;
  cursor: grab;
}
.rga-range__input:focus-visible {
  outline: none;
}
.rga-range__input:focus-visible::-webkit-slider-thumb {
  box-shadow: 0 0 0 3px rgba(217, 123, 41, 0.35);
}
.rga-range__input:focus-visible::-moz-range-thumb {
  box-shadow: 0 0 0 3px rgba(217, 123, 41, 0.35);
}
.rga-range__value {
  font-weight: 650;
  color: var(--bf-text, #1F2430);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.rga-range__reset {
  appearance: none;
  border: 1px solid var(--bf-rule, #E3E6EC);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-muted, #6B7280);
  border-radius: 999px;
  font: inherit;
  padding: 1px 9px;
  cursor: pointer;
  white-space: nowrap;
}
.rga-range__reset:hover {
  color: var(--bf-text, #1F2430);
  border-color: var(--bf-muted, #6B7280);
}
.rga-range__reset:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/* ── Ask: question chips ───────────────────────────────────────────────────
   Same look as the KPI Grid's Ask row. */
.rga-ask {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 2px 16px 8px 16px;
}
.rga-ask__row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.rga-ask__label {
  font-size: 0.9em;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-right: 2px;
}
.rga-ask__chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 4px 2px 10px;
  border-radius: 999px;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-surface-alt, #F4F5F7);
  color: var(--bf-text, #242424);
  font: inherit;
  cursor: pointer;
  transition: border-color 0.12s ease, background 0.12s ease;
}
.rga-ask__chip:hover {
  border-color: #E8612A;
}
.rga-ask__chip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.rga-ask__chip--active {
  background: rgba(232, 97, 42, 0.12);
  color: var(--bf-strong, #1F2A44);
  font-weight: 600;
}
.rga-ask__count {
  min-width: 16px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  font-size: 0.92em;
  font-weight: 700;
  line-height: 15px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.rga-ask__count--none {
  color: #1E6D6E;
}
.rga-ask__chip--active .rga-ask__count {
  color: #FFFFFF;
}
.rga-ask__answer {
  display: flex;
  align-items: baseline;
  gap: 8px;
  color: var(--bf-strong, #1F2A44);
}
.rga-ask__arrow {
  font-weight: 700;
}
.rga-ask__text {
  flex: 1 1 auto;
  font-weight: 600;
}
.rga-ask__clear {
  border: 0;
  background: transparent;
  color: var(--bf-muted, #6B7280);
  cursor: pointer;
  font: inherit;
  padding: 0 4px;
}
.rga-ask__clear:hover {
  color: var(--bf-text, #1F2430);
}
.rga-ask__clear:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/* ── Panel → board ─────────────────────────────────────────────────────── */
.rga-clickable {
  cursor: pointer;
}
.rga-clickable:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
.rga-listrow.rga-clickable:hover,
.rga-smart__item.rga-clickable:hover {
  background: var(--bf-surface-alt, #F4F5F7);
}
.rga-kpi.rga-clickable:hover {
  box-shadow: inset 0 0 0 1px var(--bf-rule, #E3E6EC);
}
.rga-kpi--active {
  background: rgba(217, 123, 41, 0.08);
  box-shadow: inset 0 0 0 1px rgba(217, 123, 41, 0.45);
}
.rga-listrow--selected {
  background: rgba(217, 123, 41, 0.08);
}
.rga-healthbar__seg.rga-clickable:hover {
  filter: brightness(1.1);
}
.rga-empty {
  padding: 18px 4px;
  color: var(--bf-muted, #6B7280);
}
.rga-empty__reset {
  appearance: none;
  border: 1px solid var(--bf-rule, #E3E6EC);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-text, #1F2430);
  border-radius: 999px;
  font: inherit;
  padding: 2px 10px;
  cursor: pointer;
}
/* ── Capacity what-if ──────────────────────────────────────────────────── */
.rga-whatif {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-left: 18px;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid transparent;
  /* On: amber frame, so a simulated board is never mistaken for the real one. */
}
.rga-whatif--on {
  border-color: #F0DCC0;
  background: rgba(217, 168, 50, 0.1);
}
button.rga-legend__whatif {
  appearance: none;
  font: inherit;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid #F0DCC0;
  background: rgba(217, 168, 50, 0.12);
  color: #8A5A18;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
}
button.rga-legend__whatif:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
/* ── Axis figures above the plot ───────────────────────────────────────── */
.rga-colhead__cell--axis {
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow: visible;
}
.rga-axis {
  display: block;
  overflow: visible;
}
/* ── Responsive ──────────────────────────────────────────────────────────
   Width classes, not @media queries: Power BI's iframe viewport is not the
   visual's viewport, so a media query fires on the wrong number. */
.rga-board.rga-medium .rga-head,
.rga-board.rga-medium .rga-lede,
.rga-board.rga-medium .rga-stats,
.rga-board.rga-medium .rga-legend,
.rga-board.rga-medium .rga-ask,
.rga-board.rga-medium .rga-rangebar {
  padding-left: 12px;
  padding-right: 12px;
}
.rga-board.rga-medium .rga-board-col {
  padding: 0 12px;
}
.rga-board.rga-medium .rga-stats {
  gap: 20px;
}
.rga-board.rga-medium .rga-lede__text {
  max-width: 240px;
}
.rga-board.rga-narrow {
  padding-top: 10px;
  /* Stacks under the key rather than being squeezed onto its line. */
}
.rga-board.rga-narrow .rga-head {
  flex-direction: column;
  align-items: stretch;
  padding-left: 10px;
  padding-right: 10px;
}
.rga-board.rga-narrow .rga-head__controls {
  margin-left: 0;
  justify-content: flex-start;
}
.rga-board.rga-narrow .rga-lede,
.rga-board.rga-narrow .rga-stats,
.rga-board.rga-narrow .rga-legend,
.rga-board.rga-narrow .rga-ask,
.rga-board.rga-narrow .rga-rangebar {
  padding-left: 10px;
  padding-right: 10px;
}
.rga-board.rga-narrow .rga-legend__horizon {
  margin-left: 0;
  flex-basis: 100%;
}
.rga-board.rga-narrow .rga-lede {
  gap: 8px;
}
.rga-board.rga-narrow .rga-stats {
  gap: 16px;
  padding-top: 10px;
}
.rga-board.rga-narrow .rga-board-col {
  padding: 0 10px;
}
.rga-board.rga-narrow .rga-slider__input {
  width: 72px;
}
/* ==========================================================================
   License chrome — src/license.ts IS THE AUTHORITY. Read this before editing.

   `BFUSION_LICENSE_CSS` in src/license.ts is injected into the document at
   runtime and therefore WINS over everything in this stylesheet. It is also
   the only place the trial watermark and the locked overlay are styled at all:
   it renders `.bfusion-trial-watermark` / `.bfusion-locked-overlay`, class
   names this file never mentions.

   That trap has already cost one round: the badge and watermark were recoloured
   here from orange to the suite's grey, the change looked complete, and the
   visual still shipped an orange badge and an orange watermark because
   license.ts had not been touched. **To restyle the badge or the watermark, edit
   src/license.ts.**

   What remains below is the positioning wrapper plus the badge rules that
   license.ts's own CSS then overrides — kept because `.bfusion-license-badge-wrap`
   is created by visual.ts, not by license.ts, so its placement does live here.
   The dead `.bfusion-watermark*` block that used to follow was removed: it
   matched nothing and read exactly like the thing that styles the watermark.
   ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
